std::vector<Point2d> convexHull2D(const std::vector<Point2d>& points) {
    if (points.size() <= 1) return points;

    auto compare = [](const Point2d& a, const Point2d& b) {
        return a.y < b.y || (a.y == b.y && a.x < b.x);
    };
    auto p0 = std::min_element(points.begin(), points.end(), compare);

    std::vector<Point2d> sortedPoints(points.begin(), points.end());
    std::sort(sortedPoints.begin(), sortedPoints.end(),
        [p0](const Point2d& a, const Point2d& b) {
            if (a == *p0) return false;
            if (b == *p0) return true;
            double crossProduct = (a.x - p0->x) * (b.y - p0->y) - (a.y - p0->y) * (b.x - p0->x);
            if (crossProduct == 0) {
                double distA = (a.x - p0->x) * (a.x - p0->x) + (a.y - p0->y) * (a.y - p0->y);
                double distB = (b.x - p0->x) * (b.x - p0->x) + (b.y - p0->y) * (b.y - p0->y);
                return distA < distB;
            }
            return crossProduct > 0;
        });

    std::vector<Point2d> hull;
    for (const auto& p : sortedPoints) {
        while (hull.size() >= 2) {
            Point2d a = hull[hull.size() - 2];
            Point2d b = hull.back();
            double crossVal = (b.x - a.x) * (p.y - a.y) - (b.y - a.y) * (p.x - a.x);
            if (crossVal <= 0) hull.pop_back();
            else break;
        }
        hull.push_back(p);
    }

    return hull;
}
