std::vector<Point2d> convexHull2D(const std::vector<Point2d>& points) {
    if (points.size() <= 1) return points;

    // Find pivot (lowest y, then leftmost)
    auto pivot = std::min_element(points.begin(), points.end(),
        [](const Point2d& a, const Point2d& b) {
            return a.y() < b.y() || (a.y() == b.y() && a.x() < b.x());
        });

    // Sort by polar angle with pivot
    std::vector<Point2d> sorted = points;
    std::sort(sorted.begin(), sorted.end(),
        [pivot](const Point2d& a, const Point2d& b) {
            if (a == *pivot) return false;
            if (b == *pivot) return true;

            double cross = (a.x() - pivot->x()) * (b.y() - pivot->y()) -
                          (a.y() - pivot->y()) * (b.x() - pivot->x());
            if (cross == 0) {
                double distA = (a.x() - pivot->x())*(a.x() - pivot->x()) +
                              (a.y() - pivot->y())*(a.y() - pivot->y());
                double distB = (b.x() - pivot->x())*(b.x() - pivot->x()) +
                              (b.y() - pivot->y())*(b.y() - pivot->y());
                return distA < distB;
            }
            return cross > 0;
        });

    // Build convex hull
    std::vector<Point2d> hull;
    for (const auto& p : sorted) {
        while (hull.size() >= 2) {
            Point2d a = hull[hull.size()-2];
            Point2d b = hull.back();
            double cross = (b.x() - a.x())*(p.y() - a.y()) -
                          (b.y() - a.y())*(p.x() - a.x());
            if (cross <= 0) hull.pop_back();
            else break;
        }
        hull.push_back(p);
    }

    return hull;
}
